 26	
 27	function mockRequest(method: string, url: string, bodyJson?: unknown): IncomingMessage {
 28	    const req = new EventEmitter() as IncomingMessage;
 29	    (req as unknown as { method: string }).method = method;
 30	    (req as unknown as { url: string }).url = url;
 31	    (req as unknown as { destroy(): void }).destroy = () => {
 32	        req.emit('error', new Error('destroyed'));
 33	    };
 34	
 35	    process.nextTick(() => {
 36	        if (bodyJson !== undefined) {
 37	            req.emit('data', Buffer.from(JSON.stringify(bodyJson)));
 38	        }
 39	        req.emit('end');
 40	    });
 41	
 42	    return req;
 43	}
 44	
 45	interface MockResponse {
 46	    statusCode: number | undefined;
 47	    body: string;
 48	    res: ServerResponse;
 49	}
 50	
 51	function mockResponse(): MockResponse {
 52	    const mock: MockResponse = {
 53	        statusCode: undefined,
 54	        body: '',
 55	        res: null as unknown as ServerResponse,
 56	    };
 57	
 58	    const res = new EventEmitter() as unknown as ServerResponse;
 59	
 60	    (res as unknown as {
 61	        writeHead(status: number, headers?: Record<string, string | number>): void;
 62	    }).writeHead = (status: number) => {
 63	        mock.statusCode = status;
 64	    };
 65	
 66	    (res as unknown as { end(body?: string): void }).end = (body?: string) => {
 67	        mock.body = body ?? '';
 68	    };
 69	
 70	    mock.res = res;
 71	    return mock;
 72	}
